import React, { useEffect, useState } from 'react'
import useWebSocket, { ReadyState } from "react-use-websocket";
import { getAccessToken } from "../../../helpers/authUtils";
import WholesalerDiscountsTable from "./WholesalerDiscountsTable";
import { useNavigate } from "react-router-dom";
import { Loading } from "../../../components";

const columns = [
  { name: "Title", uid: "title" },
  { name: "Pack Qty", uid: "pack_quantity" },
  { name: "Loose Units", uid: "loose_units" },
  { name: "Unit Qty", uid: "unit_quantity" },
  { name: "Pack Price", uid: "pack_buying_price" },
  { name: "Pack Price", uid: "pack_selling_price" },
  { name: "Mfd", uid: "manufacture_date" },
  { name: "Expiry", uid: "expiry_date" },
  { name: "Expiry Status", uid: "expiry_status" },
  { name: "Actions", uid: "actions" },
];
export default function WholesalerDiscounts() {
  const [openRetailerReceiptFormModal, setopenRetailerReceiptFormModal] =
    useState(false);
  const [userToken, setUserToken] = useState();
  const [retailerReceipt, setRetailerReceipt] = useState();
  // const [retailerReceipts, setRetailerReceipts] = useState([])

  const [updated, setUpdated] = useState(false);
  const [itemsToDisplay, setitemsToDisplay] = useState(50);
  const [modalTitle, setmodalTitle] = useState("");
  const navigate = useNavigate();
  const [retailerReceipts, setretailerReceipts] = useState([]);
  const [loading, setloading] = useState(true);

  const [data, setdata] = useState();

  useEffect(() => {
    setUserToken(getAccessToken());
  }, []);

  useEffect(() => {
    setdata(retailerReceipts);
  }, [retailerReceipts]);

  const { readyState, sendJsonMessage } = useWebSocket(
    userToken ? `ws://127.0.0.1:8000/retailers/discounts/` : null,
    {
      queryParams: {
        token: userToken ? userToken : "",
      },

      onOpen: () => {
        console.log("Connected!");
      },
      onClose: () => {
        console.log("Disconnected!");
      },
      // onMessage handler
      onMessage: (e) => {
        setretailerReceipts(JSON.parse(e.data));
        setloading(false);
      },
    }
  );

  const connectionStatus = {
    [ReadyState.CONNECTING]: "Connecting",
    [ReadyState.OPEN]: "Open",
    [ReadyState.CLOSING]: "Closing",
    [ReadyState.CLOSED]: "Closed",
    [ReadyState.UNINSTANTIATED]: "Uninstantiated",
  }[readyState];

  const handleEditAction = (item) => {
    setopenRetailerReceiptFormModal(true);

    // setUpdated(false)

    setRetailerReceipt(item);
    setmodalTitle(`${item.title}`);
  };

  const handleAddAction = () => {
    setopenRetailerReceiptFormModal(true);

    setUpdated(false);

    setmodalTitle("Add new department");
    setRetailerReceipt(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/retailers/inventory/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    navigate(`/retailers/inventory/delete/${item.id}`);
  };
  const handleFilter = (e) => {
    console.log("filter", e);

    const search_param = e;

    if (search_param && search_param !== "") {
      setdata(
        retailerReceipts.filter((x) =>
          x.title.toLowerCase().includes(search_param)
        )
      );
    } else {
      setdata(retailerReceipts);
      console.log("receipts", retailerReceipts);
      // dispatch()
    }
  };

  return (
    <div>
      {data ? (
        <WholesalerDiscountsTable
          data={data}
          columns={columns}
          editAction={handleEditAction}
          detailsAction={handleDetailsAction}
          deleteAction={handleDeleteAction}
          addAction={handleAddAction}
          handleFilter={handleFilter}
          itemsToDisplay={itemsToDisplay}
          setitemsToDisplay={setitemsToDisplay}
        />
      ) : (
        <Loading loading={loading} />
      )}
    </div>
  );
}
